import { ChangeDetectionStrategy, Component, computed, inject, ViewEncapsulation } from '@angular/core';
import { BaseComponent, PARENT_INSTANCE } from 'primeng/basecomponent';
import { Bind } from 'primeng/bind';
import { ColorChannel, getChannelColor, getChannelRange } from './color-manager';
import { INPUT_COLOR_INSTANCE, INPUT_COLOR_SLIDER_INSTANCE } from './inputcolor.token';
import type { InputColorSliderHandlePassThrough } from 'primeng/types/inputcolor';

/**
 * InputColorSliderHandle is a helper component for InputColor component.
 * @group Components
 */
@Component({
    selector: 'p-inputcolor-slider-handle',
    standalone: true,
    template: `<ng-content></ng-content>`,
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
    host: {
        '[class]': '$pc.cx("sliderHandle")',
        '[style.--px-slider-handle-background]': '$handleColor()',
        '[style.left]': '$left()',
        '[style.top]': '$top()',
        '[style.translate]': '$translate()',
        '[attr.role]': "'slider'",
        '[attr.tabindex]': '$tabindex()',
        '[attr.aria-label]': '$channel()',
        '[attr.aria-disabled]': '$ariaDisabled()',
        '[attr.aria-valuemin]': '$range().minValue',
        '[attr.aria-valuemax]': '$range().maxValue',
        '[attr.aria-valuenow]': '$value()',
        '(keydown)': 'onKeyDown($event)'
    },
    providers: [{ provide: PARENT_INSTANCE, useExisting: InputColorSliderHandle }],
    hostDirectives: [Bind]
})
export class InputColorSliderHandle extends BaseComponent<InputColorSliderHandlePassThrough> {
    componentName = 'InputColorSliderHandle';

    bindDirectiveInstance = inject(Bind, { self: true });

    $pc = inject(INPUT_COLOR_INSTANCE);

    private pcSlider = inject(INPUT_COLOR_SLIDER_INSTANCE);

    $channel = computed(() => this.pcSlider.channel());
    $isVertical = computed(() => this.pcSlider.orientation() === 'vertical');
    $range = computed(() => getChannelRange(this.$channel()));
    $value = computed(() => this.$pc.$color().getChannelValue(this.$channel() as ColorChannel));

    $tabindex = computed(() => (this.$pc.$disabled() ? -1 : 0));
    $ariaDisabled = computed(() => this.$pc.$disabled() || undefined);

    $handlePosition = computed(() => {
        const range = this.$range();
        const value = this.$value();
        const pct = ((value - range.minValue) / (range.maxValue - range.minValue)) * 100;

        return `${pct}%`;
    });

    $handlePositionVertical = computed(() => {
        const range = this.$range();
        const value = this.$value();
        const pct = 100 - ((value - range.minValue) / (range.maxValue - range.minValue)) * 100;

        return `${pct}%`;
    });

    $left = computed(() => (this.$isVertical() ? null : this.$handlePosition()));
    $top = computed(() => (this.$isVertical() ? this.$handlePositionVertical() : null));
    $translate = computed(() => (this.$isVertical() ? '0 -50%' : '-50% 0'));

    $handleColor = computed(() => getChannelColor(this.$pc.$color(), this.$channel() as ColorChannel).toRgbString());

    onAfterViewChecked() {
        this.bindDirectiveInstance.setAttrs(this.ptms(['host', 'root']));
    }

    onKeyDown(event: KeyboardEvent) {
        if (this.$pc.$disabled()) return;

        const ch = this.$channel();
        const range = this.$range();
        let value = this.$value();
        let handled = false;

        switch (event.key) {
            case 'ArrowRight':
            case 'ArrowUp':
                value = Math.min(value + range.step, range.maxValue);
                handled = true;
                break;
            case 'ArrowLeft':
            case 'ArrowDown':
                value = Math.max(value - range.step, range.minValue);
                handled = true;
                break;
            case 'PageUp':
                value = Math.min(value + range.pageStep, range.maxValue);
                handled = true;
                break;
            case 'PageDown':
                value = Math.max(value - range.pageStep, range.minValue);
                handled = true;
                break;
            case 'Home':
                value = range.minValue;
                handled = true;
                break;
            case 'End':
                value = range.maxValue;
                handled = true;
                break;
        }

        if (handled) {
            event.preventDefault();
            this.$pc.setChannelValue(ch as ColorChannel, value, event, true);
        }
    }
}
